insert into products (id, slug, "categoryId", "categorySlug", name, description, images, "isSlice", "weightOptions", tags, featured, "isInOffer", "offerId") values
  ('prod-choco-truffle', 'chocolate-truffle-cake', 'cat-birthday', 'birthday-cakes', 'Chocolate Truffle Cake', 'Rich dark chocolate sponge layered with silky truffle ganache and finished with a glossy chocolate drip. A birthday classic that never disappoints.', '["https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1517427294546-5aa121f68e8a?auto=format&fit=crop&w=1200&q=80"]'::jsonb, false, '[{"label":"600 g","grams":600,"price":999},{"label":"1 kg","grams":1000,"price":1548},{"label":"1.5 kg","grams":1500,"price":2198},{"label":"2 kg","grams":2000,"price":2747}]'::jsonb, '["Bestseller","Chocolate"]'::jsonb, true, true, '11111111-1111-1111-1111-111111111111'),
  ('prod-rainbow-funfetti', 'rainbow-funfetti-cake', 'cat-birthday', 'birthday-cakes', 'Rainbow Funfetti Cake', 'Vanilla sponge studded with rainbow sprinkles, layered with vanilla buttercream and a confetti crumb coat. Pure birthday joy.', '["https://images.unsplash.com/photo-1621303837174-89787a7d4729?auto=format&fit=crop&w=1200&q=80"]'::jsonb, false, '[{"label":"600 g","grams":600,"price":999},{"label":"1 kg","grams":1000,"price":1548},{"label":"1.5 kg","grams":1500,"price":2198},{"label":"2 kg","grams":2000,"price":2747}]'::jsonb, '["Kids'' favourite"]'::jsonb, true, true, '11111111-1111-1111-1111-111111111111'),
  ('prod-red-velvet', 'red-velvet-cake', 'cat-birthday', 'birthday-cakes', 'Red Velvet Cake', 'Velvety cocoa sponge with a hint of tang, layered with cream cheese frosting. Elegant enough for any milestone birthday.', '["https://images.unsplash.com/photo-1714949134591-d6f2c581b20d?auto=format&fit=crop&w=1200&q=80"]'::jsonb, false, '[{"label":"600 g","grams":600,"price":1099},{"label":"1 kg","grams":1000,"price":1703},{"label":"1.5 kg","grams":1500,"price":2418},{"label":"2 kg","grams":2000,"price":3022}]'::jsonb, '["Signature"]'::jsonb, false, true, '11111111-1111-1111-1111-111111111111'),
  ('prod-butterscotch', 'butterscotch-crunch-cake', 'cat-birthday', 'birthday-cakes', 'Butterscotch Crunch Cake', 'Caramelised butterscotch sponge with praline crunch and whipped butterscotch cream. A South Indian birthday favourite.', '["https://images.unsplash.com/photo-1547414368-ac947d00b91d?auto=format&fit=crop&w=1200&q=80"]'::jsonb, false, '[{"label":"600 g","grams":600,"price":949},{"label":"1 kg","grams":1000,"price":1471},{"label":"1.5 kg","grams":1500,"price":2088},{"label":"2 kg","grams":2000,"price":2610}]'::jsonb, '["Caramel"]'::jsonb, false, true, '11111111-1111-1111-1111-111111111111'),
  ('prod-ivory-rose-tier', 'ivory-rose-tiered-cake', 'cat-wedding', 'wedding-cakes', 'Ivory Rose Tiered Cake', 'A three-tier vanilla bean cake finished in smooth ivory buttercream with hand-piped sugar roses. Designed for the top table.', '["https://images.unsplash.com/photo-1535141192574-5d4897c12636?auto=format&fit=crop&w=1200&q=80"]'::jsonb, false, '[{"label":"2 kg","grams":2000,"price":2747},{"label":"3 kg","grams":3000,"price":3896},{"label":"4 kg","grams":4000,"price":4895},{"label":"5 kg","grams":5000,"price":5794}]'::jsonb, '["Tiered","Made to order"]'::jsonb, true, false, null),
  ('prod-gold-drip-wedding', 'gold-drip-wedding-cake', 'cat-wedding', 'wedding-cakes', 'Gold Drip Wedding Cake', 'Dark chocolate and salted caramel layers beneath an edible gold drip and fresh floral accents. A modern statement centrepiece.', '["https://images.unsplash.com/photo-1535254973040-607b474cb50d?auto=format&fit=crop&w=1200&q=80"]'::jsonb, false, '[{"label":"2 kg","grams":2000,"price":3022},{"label":"3 kg","grams":3000,"price":4286},{"label":"4 kg","grams":4000,"price":5385},{"label":"5 kg","grams":5000,"price":6374}]'::jsonb, '["Premium","Made to order"]'::jsonb, true, false, null),
  ('prod-pastel-floral-wedding', 'pastel-floral-wedding-cake', 'cat-wedding', 'wedding-cakes', 'Pastel Floral Wedding Cake', 'Soft pastel ombre buttercream with cascading sugar blossoms across two elegant tiers.', '["https://images.unsplash.com/photo-1771850644794-83b32d4a0b50?auto=format&fit=crop&w=1200&q=80"]'::jsonb, false, '[{"label":"2 kg","grams":2000,"price":2885},{"label":"3 kg","grams":3000,"price":4091},{"label":"4 kg","grams":4000,"price":5140},{"label":"5 kg","grams":5000,"price":6084}]'::jsonb, '["Tiered"]'::jsonb, false, false, null),
